  flex: 1;
  min-height: 0;
  padding: 0 16px 14px;
  overflow: hidden;
}
.widget__resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 22px;
  height: 22px;
  cursor: nwse-resize;
  touch-action: none;
  opacity: 0.5;
}
.widget__resize::after {
  content: '';
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 8px;
  height: 8px;
