}
.axis-line {
  stroke: var(--axis);
  stroke-width: 1;
}
.axis-text {
  font-size: 11px;
  fill: var(--text-muted);
}
.end-label {
  font-size: 12px;
  fill: var(--text-secondary);
}
.crosshair {
  stroke: var(--axis);
  stroke-width: 1;
}
.dot-ring {
  fill: var(--surface-1);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
