}
.legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.legend__line {
  width: 14px;
  height: 2px;
  border-radius: 1px;
}
.legend__swatch {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

.tip {
  position: fixed;
  top: 0;
  left: 0;
