}
.tip__row {
  display: flex;
  align-items: center;
  gap: 8px;
  line-height: 18px;
}
.tip__key {
  width: 10px;
  height: 2px;
  border-radius: 1px;
}
.tip__value {
  font-weight: 600;
  min-width: 48px;
}
.tip__name {
  color: var(--text-secondary);
}

