}
.meter__track_warning {
  --fill: var(--status-warning);
}
.meter__track_critical {
  --fill: var(--status-critical);
}
.meter__fill {
  height: 100%;
  border-radius: 4px;
  background: var(--fill, var(--accent));
}
.meter__fill_normal {
  background: var(--accent);
}
.meter__fill_warning {
  background: var(--status-warning);
}
.meter__fill_critical {
  background: var(--status-critical);
}

/* ---------- Таблицы ---------- */
.scroll {
  height: 100%;
  overflow: auto;
  margin: 0 -16px;
  padding: 0 16px;
}
.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.table th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 6px 12px 6px 0;
