}
.table .nowrap {
  white-space: nowrap;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.status_good svg {
  color: var(--status-good);
}
.status_warning svg {
  color: var(--status-warning);
}
.status_serious svg {
  color: var(--status-serious);
}
.status_critical svg {
  color: var(--status-critical);
}
