import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await (await b.newContext({ viewport: { width: 1400, height: 1500 } })).newPage();
await p.goto('http://[::1]:5199/');
await p.waitForSelector('.widget');
const pos = (t) => p.evaluate((t) => { const el = [...document.querySelectorAll('.grid__item')].find(e => e.querySelector('h2').textContent === t); return `${el.style.transform} ${Math.round(parseFloat(el.style.width))}x${Math.round(parseFloat(el.style.height))}`; }, t);
const T = 'Последние события';
const h = p.locator('.widget', { has: p.locator('h2', { hasText: T }) }).locator('.widget__resize');
let r = await h.boundingBox();
await p.mouse.move(r.x + 11, r.y + 11); await p.mouse.down();
await p.mouse.move(r.x - 1000, r.y - 600, { steps: 10 });
await p.mouse.up(); await p.waitForTimeout(300);
console.log('shrink  :', await pos(T), ' (min 4x4 cells = 440x196)');
r = await h.boundingBox();
await p.mouse.move(r.x + 11, r.y + 11); await p.mouse.down();
await p.mouse.move(r.x + 2000, r.y + 120, { steps: 10 });
await p.mouse.up(); await p.waitForTimeout(300);
console.log('grow    :', await pos(T), ' (clamped to right edge: x=565 + w<=1344)');
await b.close();
EOF
export LD_LIBRARY_PATH=/tmp/libs/usr/lib/aarch64-linux-gnu:/tmp/libs/lib/aarch64-linux-gnu FONTCONFIG_FILE=/tmp/fc/fonts.conf && node resize2.mjs

cd /tmp/pw && cat > dark.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await (await b.newContext({ viewport: { width: 1400, height: 1000 } })).newPage();
await p.goto('http://[::1]:5199/');
await p.waitForSelector('.widget');
const where = await p.evaluate(() => [...document.querySelectorAll('[class*="g-root"]')].map(e => e.tagName + '.' + e.className));
console.log(where);
await p.evaluate(() => document.querySelectorAll('[class*="g-root_theme_light"]').forEach(e => { e.classList.remove('g-root_theme_light'); e.classList.add('g-root_theme_dark'); }));
await p.waitForTimeout(300);
await p.screenshot({ path: '/tmp/pw/dark.png' });
await b.close();
EOF
